            StringBuilder b = new StringBuilder("\"");
            for (char c : ((String) v).toCharArray()) {
                if (c == '"') b.append("\\\"");
                else if (c == '\\') b.append("\\\\");
                else if (c == '\n') b.append("\\n");
                else if (c < 0x20) b.append(String.format("\\u%04x", (int) c));
                else b.append(c);
            }
            return b.append('"').toString();
        }
        if (v instanceof List) {
            StringBuilder b = new StringBuilder("[");
            boolean first = true;
            for (Object x : (List<?>) v) {
                if (!first) b.append(',');
                first = false;
                b.append(show(x));
            }
            return b.append(']').toString();
        }
        return String.valueOf(v);
    }

    static Object call(String fn, List<Object> a) throws Exception {
        switch (fn) {
            case "pack": return PackStamp.pack((Long) a.get(0), (Long) a.get(1), (Long) a.get(2), (Long) a.get(3), (Long) a.get(4), (Long) a.get(5));
            case "unpack": return PackStamp.unpack((Long) a.get(0));
            case "add_minutes": return PackStamp.addMinutes((Long) a.get(0), (Long) a.get(1));
            case "compare": return PackStamp.compare((Long) a.get(0), (Long) a.get(1));
            case "has_flag": return PackStamp.hasFlag((Long) a.get(0), (Long) a.get(1));
            case "set_flag": return PackStamp.setFlag((Long) a.get(0), (Long) a.get(1), (Boolean) a.get(2));
