            } else if (failed) {
                bad.add(label + ": unexpected error, want " + show(c.get("want")));
            } else if (!Objects.equals(got, c.get("want"))) {
                bad.add(label + ": want " + show(c.get("want")) + ", got " + show(got));
            }
        }
